window.ATLAS_ITEMS=window.ATLAS_ITEMS||{};window.ATLAS_ITEMS[243]={"id":"243","numero":243,"titre":"Hypothyroïdie","objectifs":[{"id":"243-1","rang":"A","rubrique":"Définition","titre":"Connaître la définition de l’hypothyroïdie","contenu":"<p>L'<span class=\"kw-def\">hypothyroïdie</span> est l'insuffisance de production d'<span class=\"kw-bio\">hormones thyroïdiennes</span>, par atteinte de la glande thyroïde ou, plus rarement, par défaut de stimulation de cette glande. On distingue deux mécanismes selon le siège de l'atteinte :</p>\n      <table >\n        <thead><tr><th></th><th><span class=\"kw-def\">Hypothyroïdie</span> primaire / périphérique</th><th><span class=\"kw-def\">Hypothyroïdie</span> centrale / secondaire</th></tr></thead>\n        <tbody>\n          <tr><td><strong>Siège</strong></td><td>Atteinte de la <strong>glande thyroïde</strong> — insuffisance thyroïdienne primitive ; <strong>la plus fréquente</strong></td><td>Atteinte <strong>hypothalamo-hypophysaire</strong> — <span class=\"kw-def\">insuffisance thyréotrope</span> ; rare (<span class=\"kw-chiffre\">5 %</span> des hypothyroïdes)</td></tr>\n          <tr><td><strong><span class=\"kw-bio\">TSH</span></strong></td><td><span class=\"kw-bio\">TSH</span> <strong>augmentée</strong> par levée du rétrocontrôle négatif</td><td><span class=\"kw-bio\">TSH</span> <strong>basse, normale</strong> ou peu élevée (<span class=\"kw-chiffre\">&lt; 10-12 mUI/L</span>), immunoréactive mais biologiquement inactive</td></tr>\n          <tr><td><strong><span class=\"kw-bio\">T4L</span></strong></td><td>Basse (forme patente) ou normale (forme fruste)</td><td><span class=\"kw-alerte\">Toujours basse</span> — c'est elle qui fait le diagnostic</td></tr>\n        </tbody>\n      </table>\n      <p>Selon la profondeur du déficit, l'<span class=\"kw-def\">hypothyroïdie</span> <strong>primaire</strong> se décline en deux stades :</p>\n      <table >\n        <thead><tr><th><span class=\"kw-def\">Stade</span></th><th><span class=\"kw-bio\">TSH</span></th><th><span class=\"kw-bio\">T4L</span></th></tr></thead>\n        <tbody>\n          <tr><td><strong><span class=\"kw-def\">Hypothyroïdie</span> patente</strong></td><td><span class=\"kw-bio\">TSH</span> <span class=\"kw-chiffre\">&gt; 10 mUI/L</span></td><td><span class=\"kw-bio\">T4L basse</span></td></tr>\n          <tr><td><strong><span class=\"kw-def\">Hypothyroïdie</span> fruste</strong> (infraclinique)</td><td><span class=\"kw-bio\">TSH</span> <span class=\"kw-chiffre\">4-10 mUI/L</span></td><td><span class=\"kw-bio\">T4L normale</span></td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-warn\"><strong>Piège.</strong> Le seul dosage d'une <span class=\"kw-bio\">TSH</span> modérément augmentée ne suffit <strong>pas</strong> à porter le diagnostic d'<span class=\"kw-def\">hypothyroïdie</span> ni à justifier un traitement.</div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 242 — <span class=\"kw-def\">Hyperthyroïdie</span> · 244 — Adénome hypophysaire</em></p>","frequence":0},{"id":"243-2","rang":"B","rubrique":"Epidémiologie","titre":"Connaître la prévalence de l’hypothyroïdie","contenu":"<p>L'<span class=\"kw-def\">hypothyroïdie</span> <strong>primaire</strong> est fréquente : elle concerne environ <strong><span class=\"kw-chiffre\">2 %</span></strong> de la population générale.</p>\n      <table >\n        <thead><tr><th>Paramètre</th><th>Donnée épidémiologique</th></tr></thead>\n        <tbody>\n          <tr><td><strong><span class=\"kw-def\">Prévalence</span> globale</strong></td><td><span class=\"kw-chiffre\">2 %</span> de la population générale</td></tr>\n          <tr><td><strong>Sexe</strong></td><td>Prédominance <strong>féminine</strong> : <span class=\"kw-chiffre\">7,5 %</span> des femmes contre <span class=\"kw-chiffre\">3 %</span> des hommes</td></tr>\n          <tr><td><strong>Âge</strong></td><td>Touche surtout le <strong>sujet âgé</strong> : <span class=\"kw-chiffre\">10 %</span> après <span class=\"kw-chiffre\">65 ans</span></td></tr>\n          <tr><td><strong><span class=\"kw-def\">Hypothyroïdie</span> centrale</strong></td><td>Beaucoup plus rare : <span class=\"kw-chiffre\">5 %</span> de l'ensemble des hypothyroïdes</td></tr>\n        </tbody>\n      </table>\n      <p>Depuis la généralisation du dosage de la <span class=\"kw-bio\">TSH</span>, le diagnostic est porté <strong>précocement</strong>, le plus souvent au <span class=\"kw-def\">stade</span> d'<span class=\"kw-def\">hypothyroïdie fruste</span> où seule la <span class=\"kw-bio\">TSH</span> est augmentée.</p>","frequence":0},{"id":"243-3","rang":"B","rubrique":"Physiopathologie","titre":"Connaître la physiopathologie de la thyroïdite de Hashimoto","contenu":"<p>La <span class=\"kw-def\">thyroïdite de Hashimoto</span> est une <span class=\"kw-etio\">thyroïdite auto-immune</span> caractérisée par une <strong><span class=\"kw-ttt\">infiltration</span> lympho-plasmocytaire</strong> du parenchyme thyroïdien, survenant sur un <span class=\"kw-etio\">terrain génétique prédisposant</span> (antécédents d'<span class=\"kw-etio\">auto-immunité</span>), probablement favorisée par des facteurs environnementaux mal connus.</p>\n      <p><strong>Mécanisme — destruction progressive des thyréocytes</strong> :</p>\n      <ul>\n        <li><strong>Phase initiale</strong> : <span class=\"kw-bio\">euthyroïdie</span> asymptomatique (<span class=\"kw-bio\">TSH</span> normale) ; très rarement une <span class=\"kw-clinique\">hyperthyroïdie</span> transitoire ;</li>\n        <li><strong>Phase d'état</strong> : <span class=\"kw-alerte\">hypothyroïdie</span> par destruction des thyréocytes — <span class=\"kw-bio\">TSH élevée</span>, <span class=\"kw-bio\">T4 diminuée</span> (dosage de T3 inutile).</li>\n      </ul>\n      <p><strong>Profil immunologique</strong> :</p>\n      <ul>\n        <li><span class=\"kw-bio\">Anticorps anti-thyroperoxydase</span> (<span class=\"kw-bio\">anti-TPO</span>) : titre <strong>élevé +++</strong>, marqueur principal ;</li>\n        <li><span class=\"kw-bio\">Anticorps anti-thyroglobuline</span> (<span class=\"kw-bio\">anti-Tg</span>) : positifs à un moindre degré, confirment le diagnostic ;</li>\n        <li><strong>Absence</strong> d'<span class=\"kw-bio\">anticorps anti-récepteurs</span> de la <span class=\"kw-bio\">TSH</span>.</li>\n      </ul>\n      <p><strong>Goitre</strong> : <span class=\"kw-clinique\">irrégulier</span>, très <span class=\"kw-clinique\">ferme</span>, <span class=\"kw-clinique\">pseudo-nodulaire</span>. La <span class=\"kw-def\">thyroïdite</span> de Hashimoto est la <strong>1ʳᵉ cause d'<span class=\"kw-def\">hypothyroïdie</span> en France</strong>.</p>\n      <p>Elle peut être isolée ou s'intégrer dans une <span class=\"kw-def\">polyendocrinopathie auto-immune</span> :</p>\n      <table >\n        <thead><tr><th>Polyendocrinopathie</th><th>Associations</th></tr></thead>\n        <tbody>\n          <tr><td><strong>Type 2</strong> (la plus fréquente)</td><td><span class=\"kw-etio\">Diabète de type 1</span> ; <span class=\"kw-etio\">insuffisance surrénale lente</span> ; <span class=\"kw-etio\">vitiligo</span> ; <span class=\"kw-etio\">maladie de Biermer</span></td></tr>\n          <tr><td><strong>Type 1</strong> (moins fréquente)</td><td><span class=\"kw-etio\">Hypoparathyroïdie</span> ; <span class=\"kw-etio\">insuffisance surrénale lente</span></td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-danger\"><strong><span class=\"kw-alerte\">Drapeau rouge</span>.</strong> Une <span class=\"kw-alerte\">croissance rapide</span> du goitre ou d'une zone pseudo-nodulaire en cours d'<span class=\"kw-clinique\">évolution</span> doit faire évoquer un <span class=\"kw-alerte\">lymphome thyroïdien</span> (complique &lt; <span class=\"kw-chiffre\">1 %</span> des thyroïdites auto-immunes).</div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 247 — <span class=\"kw-def\">Diabète</span> · 245 — Insuffisance surrénale · 241 — Goitre - <span class=\"kw-clinique\">nodule</span> - cancer thyroïdien</em></p>","frequence":0},{"id":"243-4","rang":"A","rubrique":"Diagnostic positif","titre":"Connaître les signes cliniques d’une hypothyroïdie","contenu":"<p>La sémiologie de l'<span class=\"kw-def\">hypothyroïdie</span> varie selon sa <strong>profondeur</strong>, son <strong>ancienneté</strong> et son <strong>origine</strong> (périphérique ou centrale). L'<span class=\"kw-def\">hypothyroïdie fruste</span>, forme la plus fréquente aujourd'hui, est peu ou pas symptomatique ; l'<span class=\"kw-def\">hypothyroïdie profonde</span>, devenue rare, est franchement symptomatique.</p>\n      <table >\n        <thead><tr><th>Appareil</th><th>Signes cliniques</th></tr></thead>\n        <tbody>\n          <tr><td><strong>Hypométabolisme</strong></td><td><span class=\"kw-clinique\">Asthénie</span> physique et psycho-intellectuelle, somnolence ; <span class=\"kw-clinique\">hypothermie</span>, frilosité <span class=\"kw-etio\">acquise</span>, diminution de la sudation ; <span class=\"kw-clinique\">constipation</span> acquise ; <span class=\"kw-clinique\">bradycardie</span>, <span class=\"kw-clinique\">hypotension artérielle</span> ; <span class=\"kw-clinique\">prise de poids modeste</span> contrastant avec une perte d'appétit</td></tr>\n          <tr><td><strong>Peau &amp; phanères</strong></td><td>Peau pâle ou jaunâtre (<span class=\"kw-clinique\">carotinodermie</span>, par baisse de transformation du carotène) ; peau sèche et squameuse ; <span class=\"kw-clinique\">dépilation diffuse</span> (signe de la queue des sourcils) ; cheveux secs et cassants</td></tr>\n          <tr><td><strong>Myxœdème cutanéomuqueux</strong></td><td>Peau infiltrée et épaisse : doigts boudinés avec <span class=\"kw-clinique\">syndrome du canal carpien</span> ; paupières infiltrées ; <span class=\"kw-clinique\">faciès lunaire</span> ; <span class=\"kw-clinique\">voix rauque</span> ; <span class=\"kw-clinique\">hypoacousie</span> ; <span class=\"kw-clinique\">macroglossie</span>, ronflements</td></tr>\n          <tr><td><strong>Neuromusculaire &amp; neuropsy</strong></td><td>Syndrome myogène (<span class=\"kw-clinique\">déficit moteur</span>, crampes, <span class=\"kw-clinique\">myalgies</span>) ; tendinites, <span class=\"kw-clinique\">arthralgies</span>, neuropathies périphériques ; <span class=\"kw-clinique\">ralentissement idéomoteur</span>, apathie, troubles de la mémoire</td></tr>\n          <tr><td><strong>Retentissement endocrinien</strong></td><td>Troubles de la libido ; troubles des règles (<span class=\"kw-clinique\">oligoménorrhée</span>, ménorragies, anovulation) ; <span class=\"kw-clinique\">galactorrhée</span> rare (hyperprolactinémie possible si <span class=\"kw-def\">hypothyroïdie</span> primaire profonde, <span class=\"kw-bio\">TSH</span> <span class=\"kw-chiffre\">&gt; 50 mUI/L</span>)</td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-warn\"><strong>Discriminant.</strong> Le <span class=\"kw-alerte\">myxœdème cutanéomuqueux est absent dans l'insuffisance thyréotrope centrale</span> — sa présence oriente vers une <span class=\"kw-def\">hypothyroïdie</span> périphérique.</div>","frequence":1},{"id":"243-5","rang":"A","rubrique":"Diagnostic positif","titre":"Connaître les anomalies des dosages hormonaux","contenu":"<p>Le diagnostic <span class=\"kw-ttt\">biologique</span> repose sur une <strong>stratégie en cascade</strong> : <span class=\"kw-bio\">TSH</span> en <strong>1ᵉʳ temps</strong>, puis <span class=\"kw-bio\">T4 libre</span> (<span class=\"kw-bio\">T4L</span>) en <strong>2ⁿᵈ temps</strong> uniquement si la <span class=\"kw-bio\">TSH</span> est anormale. La <span class=\"kw-bio\">T3 libre</span> n'est qu'un examen de 3ᵉ intention.</p>\n      <p><strong>Les trois profils hormonaux</strong> à reconnaître :</p>\n      <table >\n        <thead><tr><th>Profil</th><th><span class=\"kw-bio\">TSH</span></th><th><span class=\"kw-bio\">T4L</span></th></tr></thead>\n        <tbody>\n          <tr><td><strong><span class=\"kw-def\">Hypothyroïdie</span> patente</strong> (primaire)</td><td><span class=\"kw-bio\">TSH</span> <span class=\"kw-chiffre\">&gt; 10 mUI/L</span></td><td><span class=\"kw-bio\">T4L basse</span></td></tr>\n          <tr><td><strong><span class=\"kw-def\">Hypothyroïdie</span> fruste</strong> (primaire)</td><td><span class=\"kw-bio\">TSH</span> <span class=\"kw-chiffre\">4-10 mUI/L</span></td><td><span class=\"kw-bio\">T4L normale</span></td></tr>\n          <tr><td><strong>Insuffisance thyréotrope</strong> (centrale)</td><td><span class=\"kw-bio\">TSH</span> basse, normale ou peu élevée (<span class=\"kw-chiffre\">&lt; 10-12 mUI/L</span>)</td><td><span class=\"kw-bio\">T4L basse</span></td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-warn\"><strong>Piège.</strong> Une <span class=\"kw-bio\">TSH</span> peu élevée avec <span class=\"kw-bio\">T4L normale</span> évoque une <span class=\"kw-def\">hypothyroïdie</span> fruste, mais une <span class=\"kw-alerte\">insuffisance thyréotrope</span> donne une <span class=\"kw-bio\">TSH</span> du même ordre avec une <span class=\"kw-alerte\">T4L basse</span> — <strong>c'est la <span class=\"kw-bio\">T4L</span> qui tranche</strong>.</div>\n      <p><strong>Faux positifs de l'<span class=\"kw-def\">hypothyroïdie</span> fruste</strong> — sa <span class=\"kw-def\">prévalence</span> est surestimée car la <span class=\"kw-bio\">TSH</span> s'élève :</p>\n      <ul>\n        <li>avec l'<span class=\"kw-etio\">âge</span> : pas de seuil consensuel chez le sujet âgé ;</li>\n        <li>en situation d'<span class=\"kw-etio\">obésité</span> : élévation fonctionnelle, réversible avec la <span class=\"kw-clinique\">perte de poids</span>.</li>\n      </ul>\n      <p><strong>Stratégie de prescription du <span class=\"kw-bio\">bilan thyroïdien</span></strong> (références médicales opposables, modification UNCAM de mai 2024) :</p>\n      <table >\n        <thead><tr><th>Catégorie</th><th>Examens</th></tr></thead>\n        <tbody>\n          <tr><td><strong>1ʳᵉ intention</strong></td><td><span class=\"kw-bio\">TSH</span> seule</td></tr>\n          <tr><td><strong>2ᵉ intention</strong></td><td><span class=\"kw-bio\">T4L</span> — détermine la profondeur de l'<span class=\"kw-def\">hypothyroïdie</span> ; ± <span class=\"kw-bio\">T3L</span>, en fonction du résultat de la <span class=\"kw-bio\">TSH</span></td></tr>\n          <tr><td><strong>À visée étiologique</strong></td><td><span class=\"kw-bio\">Anticorps anti-TPO</span> (puis <span class=\"kw-bio\">anti-Tg</span> si négatifs) ; <span class=\"kw-imagerie\">échographie thyroïdienne</span> seulement en cas de <span class=\"kw-clinique\">nodule</span> palpable</td></tr>\n          <tr><td><strong>Examens inutiles</strong></td><td><span class=\"kw-bio\">T3L</span> (dernière hormone à diminuer) ; <span class=\"kw-bio\">thyroglobuline</span> (utile seulement pour certaines hypothyroïdies congénitales) ; <span class=\"kw-imagerie\">scintigraphie thyroïdienne</span></td></tr>\n        </tbody>\n      </table>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 244 — Adénome hypophysaire</em></p>","frequence":2},{"id":"243-6","rang":"B","rubrique":"Diagnostic positif","titre":"Connaître les signes biologiques spécifiques et non spécifiques","contenu":"<p>À côté des dosages hormonaux, l'<span class=\"kw-def\">hypothyroïdie</span> s'accompagne d'anomalies biologiques qu'il faut savoir distinguer en signes <strong>spécifiques</strong> et <strong>non spécifiques</strong>.</p>\n      <p><strong>Signes biologiques spécifiques</strong> — ils affirment l'<span class=\"kw-def\">hypothyroïdie</span> et orientent son origine :</p>\n      <ul>\n        <li><span class=\"kw-bio\">TSH</span> et <span class=\"kw-bio\">T4 libre</span> : font le <span class=\"kw-def\">diagnostic positif</span> et différencient les formes patente / fruste / centrale ;</li>\n        <li><span class=\"kw-bio\">Anticorps anti-TPO</span> et <span class=\"kw-bio\">anti-Tg</span> : orientent vers une origine <span class=\"kw-etio\">auto-immune</span>.</li>\n      </ul>\n      <p><strong>Signes biologiques non spécifiques</strong> — fréquents mais non diagnostiques :</p>\n      <table >\n        <thead><tr><th>Anomalie</th><th>Caractéristiques</th></tr></thead>\n        <tbody>\n          <tr><td><strong>Hématologique</strong></td><td><span class=\"kw-bio\">Anémie</span> normocytaire normochrome, plus rarement macrocytaire</td></tr>\n          <tr><td><strong>Lipidique</strong></td><td><span class=\"kw-bio\">Hypercholestérolémie</span> (élévation du <span class=\"kw-bio\">LDL</span>), quasi constante si <span class=\"kw-def\">hypothyroïdie</span> patente ; <span class=\"kw-bio\">hypertriglycéridémie</span> (VLDL), plus rare</td></tr>\n          <tr><td><strong>Enzymatique</strong></td><td>Élévation des <span class=\"kw-bio\">CPK</span> ± <span class=\"kw-bio\">ASAT</span>, par <span class=\"kw-ttt\">infiltration</span> des fibres musculaires</td></tr>\n          <tr><td><strong>Ionique</strong></td><td><span class=\"kw-bio\">Hyponatrémie</span> possible en cas d'<span class=\"kw-def\">hypothyroïdie</span> patente (par <span class=\"kw-def\">SIADH</span>)</td></tr>\n        </tbody>\n      </table>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 223 — <span class=\"kw-etio\">Dyslipidémie</span></em></p>","frequence":1},{"id":"243-7","rang":"B","rubrique":"Epidémiologie","titre":"Connaître les complications liées à l’hypothyroïdie","contenu":"<p>Les complications de l'<span class=\"kw-def\">hypothyroïdie</span> s'observent surtout dans les formes <strong>profondes et anciennes</strong>, particulièrement chez le <strong>sujet âgé</strong>.</p>\n      <table >\n        <thead><tr><th>Appareil</th><th>Complications</th></tr></thead>\n        <tbody>\n          <tr><td><strong>Cardiovasculaire</strong></td><td><strong>Atteinte fonctionnelle :</strong> <span class=\"kw-clinique\">bradycardie sinusale</span> ; baisse de la force contractile ; <span class=\"kw-alerte\">insuffisance cardiaque</span> ; <span class=\"kw-alerte\">trouble du rythme ventriculaire</span><br><strong><span class=\"kw-ttt\">Infiltration</span> :</strong> <span class=\"kw-alerte\">épanchement péricardique</span> ; <span class=\"kw-imagerie\">épanchement pleural</span> ou péritonéal<br><strong>Coronaropathie :</strong> favorisée par l'<span class=\"kw-etio\">hypercholestérolémie</span> ; peut se révéler à l'instauration du traitement substitutif</td></tr>\n          <tr><td><strong>Neuromusculaire &amp; neuropsy</strong></td><td><span class=\"kw-clinique\">Apnées du sommeil</span> ; <span class=\"kw-clinique\">myopathie proximale</span> (<span class=\"kw-bio\">CPK</span> élevées) ; état dépressif, <span class=\"kw-alerte\">syndrome confusionnel</span>, démence (surtout sujet âgé)</td></tr>\n          <tr><td><strong>Digestive</strong></td><td>Ralentissement majeur du transit : <span class=\"kw-alerte\">iléus paralytique</span>, <span class=\"kw-alerte\">mégacôlon</span> (surtout sujet âgé)</td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-danger\"><strong><span class=\"kw-alerte\">Urgence</span> — <span class=\"kw-clinique\">coma</span> myxœdémateux (rang C).</strong> Rare, de <span class=\"kw-alerte\">pronostic sévère</span>. <span class=\"kw-def\">Terrain</span> d'<span class=\"kw-def\">hypothyroïdie</span> primaire profonde et ancienne (<span class=\"kw-bio\">TSH</span> <span class=\"kw-chiffre\">&gt; 50 mUI/L</span>, <span class=\"kw-bio\">T4L</span> effondrée), volontiers en période hivernale, favorisé par une <span class=\"kw-etio\">agression</span> (infection, <span class=\"kw-ttt\">chirurgie</span>, traitement sédatif ou antidépresseur). Tableau : <span class=\"kw-alerte\">coma calme, hypotonique et hypothermique</span> avec <span class=\"kw-clinique\">bradycardie</span>, <span class=\"kw-clinique\">bradypnée</span>, <span class=\"kw-clinique\">hypotension</span> ; <span class=\"kw-bio\">hyponatrémie de dilution</span> constante.</div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 339 — <span class=\"kw-clinique\">Syndrome coronarien</span> aiguë</em></p>","frequence":0},{"id":"243-8","rang":"B","rubrique":"Epidémiologie","titre":"Connaître les facteurs de risque de l’hypothyroïdie","contenu":"<p>Plusieurs terrains et expositions augmentent le risque d'<span class=\"kw-def\">hypothyroïdie</span> — leur recherche oriente le <span class=\"kw-def\">dépistage</span> ciblé.</p>\n      <table >\n        <thead><tr><th>Catégorie</th><th><span class=\"kw-def\">Facteurs de risque</span></th></tr></thead>\n        <tbody>\n          <tr><td><strong><span class=\"kw-def\">Terrain</span> <span class=\"kw-etio\">auto-immun</span></strong></td><td>Antécédent personnel ou familial d'<span class=\"kw-etio\">auto-immunité</span> ; <span class=\"kw-def\">terrain</span> prédisposant : <span class=\"kw-etio\">syndrome de Turner</span>, déficits immunitaires combinés</td></tr>\n          <tr><td><strong><span class=\"kw-etio\">Génétique</span></strong></td><td><span class=\"kw-etio\">Trisomie 21</span></td></tr>\n          <tr><td><strong>Polyendocrinopathie</strong></td><td><span class=\"kw-etio\">Polyendocrinopathie auto-immune</span>, notamment de type 2 (associée au <span class=\"kw-def\"><span class=\"kw-def\">diabète</span> de type 1</span>)</td></tr>\n          <tr><td><strong><span class=\"kw-etio\">Iatrogène</span></strong></td><td><span class=\"kw-etio\">Radiothérapie cervicale</span> (cancers ORL, lymphomes) ; <span class=\"kw-etio\">médicament iodé</span> ; <span class=\"kw-etio\">immunothérapie</span></td></tr>\n          <tr><td><strong><span class=\"kw-def\">Thyroïdite</span> lytique</strong></td><td><span class=\"kw-def\">Thyroïdite</span> avec thyrotoxicose initiale : <span class=\"kw-etio\">De Quervain</span>, thyroïdites iodées</td></tr>\n        </tbody>\n      </table>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 247 — <span class=\"kw-def\">Diabète</span> · 245 — Insuffisance surrénale</em></p>","frequence":0},{"id":"243-9","rang":"A","rubrique":"Étiologies","titre":"Connaître les principales étiologies des hypothyroïdies","contenu":"<p>Les étiologies se répartissent selon le siège de l'atteinte : <strong>hypothyroïdies primaires</strong> (glande thyroïde) et <strong>insuffisances thyréotropes</strong> (région hypothalamo-hypophysaire).</p>\n      <p><strong>1. Hypothyroïdies primaires</strong></p>\n      <table >\n        <thead><tr><th>Mécanisme</th><th>Étiologies</th></tr></thead>\n        <tbody>\n          <tr><td><strong>Thyroïdites auto-immunes</strong><br>(lymphocytaires, ≈<span class=\"kw-chiffre\"> 54 %</span>)</td><td><span class=\"kw-etio\">Thyroïdite de Hashimoto +++</span>, 1ʳᵉ cause en France ; <span class=\"kw-etio\">thyroïdite atrophique</span> (fréquente après <span class=\"kw-chiffre\">50 ans</span>, thyroïde à peine palpable, <span class=\"kw-bio\">anti-TPO</span> modérés) ; <span class=\"kw-etio\">thyroïdite du post-partum</span></td></tr>\n          <tr><td><strong>Thyroïdites iatrogènes</strong><br>(≈<span class=\"kw-chiffre\"> 15 %</span>)</td><td><span class=\"kw-etio\">Radiothérapie cervicale</span> ; <span class=\"kw-etio\">iode radioactif</span> ; <span class=\"kw-ttt\">ITK</span> et <span class=\"kw-ttt\">immunothérapies</span> / inhibiteurs de check-point ; traitements iodés (<span class=\"kw-ttt\">amiodarone</span>, PDC iodés) ; <span class=\"kw-ttt\">interférons</span> ; <span class=\"kw-ttt\">lithium</span> (goitre surtout)</td></tr>\n          <tr><td><strong>Congénitales</strong></td><td><span class=\"kw-etio\">Ectopie</span> thyroïdienne ; <span class=\"kw-etio\">athyréose</span> ; anomalie de l'hormonosynthèse</td></tr>\n          <tr><td><strong>Carence iodée</strong></td><td>1ʳᵉ cause de <span class=\"kw-clinique\">goitre</span> à l'échelle mondiale</td></tr>\n          <tr><td><strong>Autres</strong></td><td><span class=\"kw-def\">Thyroïdite</span> de <span class=\"kw-etio\">Riedel</span> (exceptionnelle) ; séquelles de <span class=\"kw-def\">thyroïdite</span> de <span class=\"kw-etio\">De Quervain</span></td></tr>\n        </tbody>\n      </table>\n      <p><strong>2. Insuffisances thyréotropes</strong> (centrales) — une <span class=\"kw-imagerie\">IRM</span> hypophysaire est systématique :</p>\n      <table >\n        <thead><tr><th>Mécanisme</th><th>Étiologies</th></tr></thead>\n        <tbody>\n          <tr><td><strong><span class=\"kw-etio\">Tumoral</span> / infiltratif</strong></td><td><span class=\"kw-etio\">Adénome hypophysaire</span> (le plus souvent), méningiome, craniopharyngiome ; maladies infiltratives (granulomatoses)</td></tr>\n          <tr><td><strong>Lésionnel</strong></td><td>Traumatisme crânien ; <span class=\"kw-def\">méningite</span> ; hémorragie méningée ; apoplexie pituitaire ; <span class=\"kw-etio\">syndrome de Sheehan</span> ; hypophysite lymphocytaire (souvent en post-partum)</td></tr>\n          <tr><td><strong><span class=\"kw-etio\">Iatrogène</span></strong></td><td><span class=\"kw-ttt\">Radiothérapie</span> de la région hypothalamo-hypophysaire ; immunothérapie (anti-CTLA4) ; bexarotène</td></tr>\n          <tr><td><strong><span class=\"kw-etio\">Congénital</span></strong></td><td>Le plus souvent <span class=\"kw-etio\">déficit hypophysaire combiné</span></td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-info\"><strong>À retenir.</strong> L'<span class=\"kw-ttt\">amiodarone</span> peut causer aussi bien des hypothyroïdies que des hyperthyroïdies ; une <span class=\"kw-def\">thyroïdite</span> <span class=\"kw-etio\">iatrogène</span> peut survenir <strong>des années après</strong> un traitement iodé ou une <span class=\"kw-ttt\">radiothérapie</span> cervicale, d'où la nécessité d'un dosage annuel de la <span class=\"kw-bio\">TSH</span>.</div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 241 — Goitre - <span class=\"kw-clinique\">nodule</span> - cancer thyroïdien · 242 — <span class=\"kw-def\">Hyperthyroïdie</span> · 244 — Adénome hypophysaire</em></p>","frequence":1},{"id":"243-10","rang":"A","rubrique":"Prise en charge","titre":"Connaître le principe de l’hormonothérapie substitutive dans l’hypothyroïdie","contenu":"<p>Le traitement de l'<span class=\"kw-def\">hypothyroïdie</span> est une <strong>hormonothérapie substitutive à vie</strong>, reposant sur la <span class=\"kw-ttt\">lévothyroxine</span>.</p>\n      <p><strong>Molécules disponibles</strong> :</p>\n      <table >\n        <thead><tr><th>Molécule</th><th>Modalités</th></tr></thead>\n        <tbody>\n          <tr><td><strong><span class=\"kw-ttt\">Lévothyroxine</span> (L-T4)</strong></td><td>Traitement de référence ; besoins moyens <span class=\"kw-chiffre\">1 à 1,5 µg/kg/j</span>, fonction de la profondeur ; per os (comprimé, solution buvable) ou injectable si <span class=\"kw-clinique\">coma</span> myxœdémateux / impossibilité d'avaler</td></tr>\n          <tr><td><strong><span class=\"kw-ttt\">Association T4 + T3</span></strong></td><td>Euthyral® — possible</td></tr>\n          <tr><td><strong><span class=\"kw-ttt\">T3 seule</span></strong></td><td>Cynomel® — indications rares</td></tr>\n        </tbody>\n      </table>\n      <p><strong>Objectifs et <span class=\"kw-def\">surveillance</span></strong> — ils diffèrent selon l'origine de l'<span class=\"kw-def\">hypothyroïdie</span> :</p>\n      <table >\n        <thead><tr><th></th><th><span class=\"kw-def\">Hypothyroïdie</span> primaire</th><th>Insuffisance thyréotrope</th></tr></thead>\n        <tbody>\n          <tr><td><strong>Paramètre de <span class=\"kw-def\">suivi</span></strong></td><td><span class=\"kw-bio\">TSH</span> seule</td><td><span class=\"kw-bio\">T4L</span> — la <span class=\"kw-alerte\">TSH ne doit pas être utilisée</span> (effondrée si substitution correcte)</td></tr>\n          <tr><td><strong>Objectif</strong></td><td><span class=\"kw-bio\">TSH</span> <span class=\"kw-chiffre\">0,5-2,5 mUI/L</span> (situation standard et <span class=\"kw-ci\">grossesse</span>)</td><td><span class=\"kw-bio\">T4L</span> <span class=\"kw-chiffre\">&gt; 50-75 %</span> de la normale</td></tr>\n          <tr><td><strong><span class=\"kw-def\">Surveillance</span></strong></td><td>1ᵉʳ contrôle à <span class=\"kw-chiffre\">4-8 semaines</span>, puis à <span class=\"kw-chiffre\">M6</span>, puis <strong>annuel</strong></td><td>Contrôle à <span class=\"kw-chiffre\">J15-21</span>, à jeun avant la prise de <span class=\"kw-ttt\">lévothyroxine</span></td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-warn\"><strong>Piège.</strong> Un contrôle de <span class=\"kw-bio\">TSH</span> <strong>trop précoce</strong> (avant <span class=\"kw-chiffre\">4-8 semaines</span>) conduit à augmenter trop vite les doses par <span class=\"kw-alerte\">inertie thyréotrope</span> — risque de surdosage. Tout <span class=\"kw-alerte\">surdosage en thyroxine</span> est <span class=\"kw-ci\">à éviter</span> (risques osseux et cardiovasculaires de la thyrotoxicose).</div>\n      <div class=\"callout callout-info\"><strong><span class=\"kw-ci\">Grossesse</span> chez une hypothyroïdienne connue (rang C).</strong> Les besoins en <span class=\"kw-ttt\">lévothyroxine</span> augmentent d'environ <span class=\"kw-chiffre\">25 à 50 %</span> dès le <strong>1ᵉʳ trimestre</strong> (la thyroïde fœtale n'est pas encore fonctionnelle, le développement neurologique dépend des hormones maternelles) : <strong>augmenter la posologie dès le diagnostic de grossesse</strong>, puis surveiller la <span class=\"kw-bio\">TSH</span> <strong>tous les mois</strong> pour la maintenir <span class=\"kw-chiffre\">&lt; 2,5 mUI/L</span>.</div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 339 — <span class=\"kw-clinique\">Syndrome coronarien</span> aiguë</em></p>","frequence":3},{"id":"243-11","rang":"A","rubrique":"Prise en charge","titre":"Comprendre les spécificités thérapeutiques du traitement de l’hypothyroïdie chez le sujet âgé et/ou coronarien","contenu":"<p>Chez le <strong>sujet âgé</strong> et/ou <strong>coronarien</strong>, l'instauration de la <span class=\"kw-ttt\">lévothyroxine</span> doit être prudente : le retour à l'euthyroïdie peut <span class=\"kw-alerte\">démasquer une coronaropathie</span>, d'autant plus que l'<span class=\"kw-def\">hypothyroïdie</span> est profonde et ancienne.</p>\n      <p><strong>Modalités d'instauration</strong> :</p>\n      <ul>\n        <li>Posologie initiale <strong>faible</strong> : <span class=\"kw-chiffre\">12,5 à 25 µg/j</span> ;</li>\n        <li>Augmentation <strong>progressive</strong> par paliers de <span class=\"kw-chiffre\">12,5 à 25 µg</span> toutes les <span class=\"kw-chiffre\">1 à 2 semaines</span> ;</li>\n        <li>Chez le coronarien non contrôlé : <strong>traiter d'abord la coronaropathie</strong>, puis normaliser la <span class=\"kw-bio\">TSH</span> ;</li>\n        <li>Cible de <span class=\"kw-bio\">TSH</span> revue à la hausse — <span class=\"kw-chiffre\">≈ 10 mUI/L</span> en cas de coronaropathie non contrôlée, selon la tolérance.</li>\n      </ul>\n      <p><strong><span class=\"kw-def\">Surveillance</span> cardiologique</strong> :</p>\n      <table >\n        <thead><tr><th>Situation</th><th>Surveillance <span class=\"kw-bio\">ECG</span></th></tr></thead>\n        <tbody>\n          <tr><td><strong>Coronaropathie grave</strong></td><td><span class=\"kw-clinique\">ECG hebdomadaire</span> si possible</td></tr>\n          <tr><td><strong>Coronaropathie récente ou non contrôlée</strong></td><td><span class=\"kw-alerte\">Hospitalisation</span> à l'initiation ; <span class=\"kw-def\">surveillance</span> clinique + <span class=\"kw-clinique\">ECG quotidien</span></td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-warn\"><strong>À faire.</strong> Prévenir le patient âgé ou coronarien qu'il doit <strong>consulter en cas de <span class=\"kw-clinique\">douleur thoracique</span></strong>. Les <span class=\"kw-ttt\">β-bloquants</span> sont parfois utiles en association à la <span class=\"kw-ttt\">lévothyroxine</span>.</div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 339 — <span class=\"kw-clinique\">Syndrome coronarien</span> aiguë</em></p>","frequence":0}],"astuces":[],"strategie":{"urgence":"<p><strong><span class=\"kw-alerte\">Coma</span> myxœdémateux :</strong> <span class=\"kw-alerte\">urgence rare au pronostic sévère</span>, survenant sur une <span class=\"kw-etio\">hypothyroïdie primaire profonde et ancienne</span> (<span class=\"kw-bio\">TSH</span> <span class=\"kw-chiffre\">&gt; 50 mUI/L</span>, <span class=\"kw-bio\">T4L effondrée</span>), volontiers en période hivernale et favorisé par une <span class=\"kw-alerte\">agression</span> (infection, <span class=\"kw-ttt\">chirurgie</span>, sédatif ou antidépresseur).<br><strong>Tableau :</strong> <span class=\"kw-alerte\">coma calme, hypotonique et hypothermique</span> avec <span class=\"kw-clinique\">bradycardie</span>, <span class=\"kw-clinique\">bradypnée</span> et <span class=\"kw-clinique\">hypotension</span> ; <span class=\"kw-bio\">hyponatrémie de dilution</span> constante ; ROT lents sans signe de localisation.<br><strong>1ᵉʳ geste :</strong> <span class=\"kw-ttt\">lévothyroxine en solution injectable</span> (en cas d'impossibilité d'avaler).<br><strong>À l'instauration du traitement :</strong> risque de <span class=\"kw-alerte\">démasquage d'une coronaropathie</span>, d'autant plus que l'hypothyroïdie est profonde et ancienne — consulter en <span class=\"kw-alerte\">urgence</span> si <span class=\"kw-alerte\">douleur thoracique</span>.</p>","hospit":"<p><strong>Ambulatoire :</strong> la prise en charge de l'<span class=\"kw-def\">hypothyroïdie</span> est <strong>ambulatoire</strong> dans la grande majorité des cas — substitution par <span class=\"kw-ttt\">lévothyroxine</span> per os avec <span class=\"kw-def\">surveillance</span> <span class=\"kw-ttt\">biologique</span> en ville.<br><strong><span class=\"kw-alerte\">Hospitalisation</span> à l'initiation :</strong> <span class=\"kw-alerte\">coronarien récent ou non contrôlé</span> — surveillance clinique + <span class=\"kw-ttt\">ECG quotidien</span>.<br><strong><span class=\"kw-alerte\">Urgence</span> :</strong> <span class=\"kw-alerte\">coma myxœdémateux</span>.<br><strong>Avis spécialisé / imagerie :</strong> <span class=\"kw-etio\">insuffisance thyréotrope</span> (atteinte centrale) → <span class=\"kw-imagerie\">IRM hypothalamo-hypophysaire</span> systématique, recherche d'un <span class=\"kw-etio\">hypopituitarisme</span> ou d'un syndrome <span class=\"kw-etio\">tumoral</span> sellaire.</p>","redflags":"<ul><li><span class=\"kw-alerte\">Coma myxœdémateux</span> : <span class=\"kw-alerte\">coma</span> calme, hypotonique et hypothermique avec <span class=\"kw-clinique\">bradycardie</span>, <span class=\"kw-clinique\">bradypnée</span> et <span class=\"kw-bio\">hyponatrémie</span> (hypothyroïdie profonde, <span class=\"kw-bio\">TSH</span> <span class=\"kw-chiffre\">&gt; 50 mUI/L</span>)</li><li><span class=\"kw-alerte\">Croissance rapide du goitre</span> ou d'une zone pseudo-nodulaire au cours d'une thyroïdite → évoquer un <span class=\"kw-alerte\">lymphome thyroïdien</span> (&lt; <span class=\"kw-chiffre\">1 %</span> des thyroïdites auto-immunes)</li><li>Atteinte cardiaque : <span class=\"kw-alerte\">insuffisance cardiaque</span>, <span class=\"kw-alerte\">trouble du rythme ventriculaire</span>, <span class=\"kw-alerte\">épanchement péricardique</span> (± pleural ou péritonéal)</li><li><span class=\"kw-alerte\">Démasquage d'une coronaropathie</span> à l'instauration de la <span class=\"kw-ttt\">lévothyroxine</span> — apparition de <span class=\"kw-clinique\">douleurs thoraciques</span></li><li>Sujet âgé : manifestations occlusives (<span class=\"kw-alerte\">iléus paralytique</span>, <span class=\"kw-alerte\">mégacôlon</span>) ; <span class=\"kw-clinique\">syndrome confusionnel</span>, état dépressif, démence</li></ul>","principes":"<p>Substitution par <span class=\"kw-ttt\">lévothyroxine</span> (L-T4) per os, dose moyenne <span class=\"kw-chiffre\">1 à 1,5 µg/kg/jour</span> fonction de la profondeur ; l'<strong>indication</strong> et la <strong>posologie initiale</strong> dépendent du <span class=\"kw-def\">stade</span> (patente <span class=\"kw-bio\">vs</span> fruste) et du <span class=\"kw-def\">terrain</span> (âge, cœur, <span class=\"kw-ci\">grossesse</span>).</p><p><strong>Hypothyroïdie patente (primaire)</strong></p><p>Adulte jeune sans <span class=\"kw-def\">comorbidité</span> : dose substitutive d'emblée.</p><ul><li><span class=\"kw-ttt\">Lévothyroxine</span> (L-T4) per os, en substitution <strong>à vie</strong></li><li>Dose moyenne <span class=\"kw-chiffre\">1 à 1,5 µg/kg/jour</span>, ajustée à la profondeur du déficit</li></ul><p><strong>Hypothyroïdie fruste — stratification du risque de conversion</strong></p><ul><li><strong>Risque élevé</strong> (<span class=\"kw-bio\">TSH</span> <span class=\"kw-chiffre\">&gt; 10 mUI/L</span> et/ou <span class=\"kw-bio\">anti-TPO</span> positifs) : <span class=\"kw-ttt\">traitement recommandé</span></li><li><strong>Risque faible</strong> (<span class=\"kw-bio\">TSH</span> <span class=\"kw-chiffre\">&lt; 10 mUI/L</span> + absence d'<span class=\"kw-bio\">anti-TPO</span>) : <span class=\"kw-ttt\">surveillance de la TSH</span> à <span class=\"kw-chiffre\">6 mois</span> puis tous les ans</li><li><strong>Risque intermédiaire</strong> (<span class=\"kw-bio\">anti-TPO</span>, signes cliniques ou hypercholestérolémie) : <span class=\"kw-ttt\">traitement à discuter</span></li><li>Besoins moindres : <span class=\"kw-chiffre\">25-75 µg/jour</span></li></ul><p><strong>Sujet âgé et/ou coronarien</strong></p><p>Coronarien récent / non contrôlé → <span class=\"kw-alerte\">hospitalisation</span> + <span class=\"kw-imagerie\">ECG</span> quotidien ; coronarien grave → <span class=\"kw-imagerie\">ECG</span> hebdomadaire.</p><ul><li>Posologie initiale <strong>faible</strong> : <span class=\"kw-ttt\">12,5 à 25 µg/jour</span></li><li>Augmentation par <strong>paliers</strong> de <span class=\"kw-chiffre\">12,5 à 25 µg</span> toutes les <span class=\"kw-chiffre\">1 à 2 semaines</span></li><li>Chez le coronarien : <span class=\"kw-ttt\">traiter d'abord la coronaropathie</span> puis normaliser la <span class=\"kw-bio\">TSH</span></li><li><span class=\"kw-ci\">Surdosage à éviter</span> : risques osseux et cardiovasculaires de la thyrotoxicose</li></ul><p><strong><span class=\"kw-ci\">Grossesse</span></strong></p><ul><li><span class=\"kw-ttt\">Traitement</span> par <span class=\"kw-ttt\">lévothyroxine</span> justifié dès que la <span class=\"kw-bio\">TSH</span> est <span class=\"kw-chiffre\">≥ 3 mUI/L</span></li><li>Femme hypothyroïdienne connue : <span class=\"kw-ttt\">augmenter les doses de 25 à 50 %</span> dès le diagnostic de <span class=\"kw-ci\">grossesse</span></li><li>Objectif : maintenir la <span class=\"kw-bio\">TSH</span> <span class=\"kw-chiffre\">&lt; 2,5 mUI/L</span>, contrôlée tous les mois</li></ul><p><strong>Insuffisance thyréotrope (centrale)</strong></p><ul><li>Modalités identiques par <span class=\"kw-ttt\">lévothyroxine</span></li><li><span class=\"kw-ci\">La TSH ne doit pas servir au suivi</span> : <span class=\"kw-def\">surveillance</span> sur la <span class=\"kw-bio\">T4L</span></li><li><span class=\"kw-ttt\">β-bloquants</span> parfois utiles en association</li></ul>","suivi":"<p><strong>Hypothyroïdie primaire :</strong> équilibre apprécié sur la <span class=\"kw-bio\">TSH seule</span> — 1ᵉʳ contrôle à <span class=\"kw-chiffre\">4-8 semaines</span> (jamais plus tôt, risque de surdosage par inertie thyréotrope), puis à <span class=\"kw-chiffre\">M6</span>, puis <strong>annuel</strong>. Objectif <span class=\"kw-bio\">TSH</span> <span class=\"kw-chiffre\">0,5-2,5 mUI/L</span> ; <span class=\"kw-chiffre\">~10 mUI/L</span> si coronaropathie non contrôlée ou sujet très âgé.<br><strong>Insuffisance thyréotrope :</strong> <span class=\"kw-def\">surveillance</span> sur la <span class=\"kw-bio\">T4L</span> (<span class=\"kw-ci\">la TSH n'est pas utilisable</span>, souvent effondrée) — 1ᵉʳ contrôle à <span class=\"kw-chiffre\">J15-21</span>, à jeun avant la prise. Objectif <span class=\"kw-bio\">T4L</span> <span class=\"kw-chiffre\">&gt; 50-75 % de la normale</span>.<br><strong>Tout contrôle de <span class=\"kw-bio\">TSH</span> :</strong> à au moins <span class=\"kw-chiffre\">6 semaines</span> d'intervalle.<br><strong><span class=\"kw-ci\">Grossesse</span> :</strong> <span class=\"kw-bio\">TSH</span> mensuelle, maintenue <span class=\"kw-chiffre\">&lt; 2,5 mUI/L</span>.</p>"},"liensGlobaux":[{"href":"https://www.sfendocrino.org/item-240-hypoglycemie-chez-ladulte-et-lenfant/","label":"SFE — Item 240 hypoglycemie chez ladulte et lenfant"},{"href":"https://radiopaedia.org/articles/hashimoto-thyroiditis","label":"Radiopaedia : Hashimoto thyroiditis"},{"href":"https://radiopaedia.org/articles/postpartum-thyroiditis-2","label":"Radiopaedia : Postpartum thyroiditis 2"}],"arbre":{"rootId":"root","nodes":[{"id":"root","kind":"root","label":"Dosage de la TSH (1ʳᵉ intention) — Devant une suspicion d'hypothyroïdie","detail":"<h4>CAT — Hypothyroïdie : du dosage hormonal à la décision thérapeutique — <span class=\"kw-bio\">TSH</span> en 1ʳᵉ intention → <span class=\"kw-bio\">T4L</span> → orientation (fruste / patente / centrale) → substitution adaptée au <span class=\"kw-def\">terrain</span></h4>","branches":[{"to":"q-t4l","label":"TSH élevée","color":"amber"},{"to":"t-centrale","label":"TSH normale/basse mais T4L basse (profil inadapté)","color":"blue"}]},{"id":"q-t4l","kind":"decision","label":"Dosage de la T4 libre (T4L) — TSH élevée, contrôlée à ≥ 6 semaines d'intervalle","branches":[{"to":"q-fruste","label":"T4L normale → hypothyroïdie fruste","color":"amber"},{"to":"q-terrain","label":"T4L basse → hypothyroïdie patente","color":"amber"}]},{"id":"q-fruste","kind":"decision","label":"Hypothyroïdie fruste — stratifier le risque de conversion — TSH 4-10 mUI/L, T4L normale","branches":[{"to":"t-fruste-traiter","label":"TSH > 10 mUI/L et/ou anti-TPO +","color":"amber"},{"to":"t-fruste-surv","label":"TSH < 10 + anti-TPO absents","color":"green"},{"to":"t-fruste-discuter","label":"Risque intermédiaire","color":"amber"},{"to":"t-grossesse","label":"Grossesse : TSH ≥ 3 mUI/L","color":"amber"}]},{"id":"t-fruste-traiter","kind":"terminal","label":"Traitement par lévothyroxine recommandé — Risque élevé de conversion","color":"amber","detail":"<h4>Traitement</h4><ul><li><span class=\"kw-ttt\">Lévothyroxine</span> <span class=\"kw-chiffre\">25-75 µg/jour</span></li><li>Indiqué si <span class=\"kw-bio\">TSH</span> <span class=\"kw-chiffre\">&gt; 10 mUI/L</span> et/ou <span class=\"kw-bio\">anti-TPO</span> positifs</li></ul>"},{"id":"t-fruste-surv","kind":"terminal","label":"Surveillance simple, pas de traitement — Risque faible","color":"green","detail":"<h4><span class=\"kw-def\">Surveillance</span></h4><ul><li><span class=\"kw-bio\">TSH</span> <span class=\"kw-chiffre\">&lt; 10 mUI/L</span> + absence d'<span class=\"kw-bio\">anti-TPO</span></li><li>Contrôle de la <span class=\"kw-bio\">TSH</span> à <span class=\"kw-chiffre\">6 mois</span> puis tous les ans</li></ul>"},{"id":"t-fruste-discuter","kind":"terminal","label":"Traitement à discuter au cas par cas — Risque intermédiaire","color":"amber","detail":"<h4>Conduite</h4><ul><li>Décision selon présence d'<span class=\"kw-bio\">anti-TPO</span>, de <span class=\"kw-clinique\">signes cliniques d'hypothyroïdie</span> ou d'une <span class=\"kw-bio\">hypercholestérolémie</span></li></ul>"},{"id":"t-grossesse","kind":"terminal","label":"Grossesse : traiter dès TSH ≥ 3 mUI/L","color":"amber","detail":"<h4>Conduite</h4><ul><li><span class=\"kw-ttt\">Lévothyroxine</span> dès <span class=\"kw-bio\">TSH</span> <span class=\"kw-chiffre\">≥ 3 mUI/L</span> ; objectif <span class=\"kw-bio\">TSH</span> <span class=\"kw-chiffre\">&lt; 2,5 mUI/L</span>, contrôle mensuel</li><li>Femme déjà traitée : <span class=\"kw-ttt\">augmenter les doses de 25-50 %</span> dès le diagnostic de <span class=\"kw-ci\">grossesse</span></li></ul>"},{"id":"q-terrain","kind":"decision","label":"Hypothyroïdie patente — quel terrain ? — TSH > 10 mUI/L, T4L basse","branches":[{"to":"t-standard","label":"Adulte sans cardiopathie","color":"green"},{"to":"q-corona","label":"Sujet âgé / coronarien","color":"amber"}]},{"id":"t-standard","kind":"terminal","label":"Lévothyroxine à dose substitutive d'emblée — Adulte sans cardiopathie","color":"green","detail":"<h4>Traitement</h4><ul><li><span class=\"kw-ttt\">Lévothyroxine</span> <span class=\"kw-chiffre\">1 à 1,5 µg/kg/jour</span>, à vie</li></ul><h4><span class=\"kw-def\">Surveillance</span></h4><ul><li><span class=\"kw-bio\">TSH</span> à <span class=\"kw-chiffre\">4-8 semaines</span>, puis <span class=\"kw-chiffre\">M6</span>, puis annuelle ; objectif <span class=\"kw-chiffre\">0,5-2,5 mUI/L</span></li></ul>"},{"id":"q-corona","kind":"decision","label":"La coronaropathie est-elle contrôlée ?","branches":[{"to":"t-corona-amb","label":"Coronaropathie contrôlée / stable","color":"amber"},{"to":"t-corona-hosp","label":"Coronaropathie récente ou non contrôlée","color":"red"}]},{"id":"t-corona-amb","kind":"terminal","label":"Initiation prudente, ambulatoire — Coronarien stable / sujet très âgé","color":"amber","detail":"<h4>Traitement</h4><ul><li>Dose initiale faible <span class=\"kw-ttt\">12,5 à 25 µg/jour</span></li><li>Paliers de <span class=\"kw-chiffre\">12,5-25 µg</span> toutes les <span class=\"kw-chiffre\">1-2 semaines</span></li><li><span class=\"kw-ttt\">Traiter d'abord la coronaropathie</span> puis normaliser la <span class=\"kw-bio\">TSH</span></li></ul><h4><span class=\"kw-def\">Surveillance</span></h4><ul><li><span class=\"kw-ttt\">ECG hebdomadaire</span> si coronarien grave</li><li>Objectif <span class=\"kw-bio\">TSH</span> <span class=\"kw-chiffre\">~10 mUI/L</span> si coronaropathie non contrôlée / sujet très âgé</li><li>Prévenir : consulter en cas de <span class=\"kw-alerte\">douleur thoracique</span></li></ul>"},{"id":"t-corona-hosp","kind":"terminal","label":"Hospitalisation à l'initiation du traitement — Coronarien récent ou non contrôlé","color":"red","detail":"<h4>Conduite</h4><ul><li><span class=\"kw-alerte\">Hospitalisation</span> dès l'instauration de la <span class=\"kw-ttt\">lévothyroxine</span></li></ul><h4><span class=\"kw-def\">Surveillance</span></h4><ul><li><span class=\"kw-def\">Surveillance</span> clinique + <span class=\"kw-ttt\">ECG quotidien</span></li><li>Titration lente à dose initiale prudente</li></ul>"},{"id":"t-centrale","kind":"terminal","label":"Insuffisance thyréotrope (hypothyroïdie centrale)","color":"blue","detail":"<h4>Paraclinique</h4><ul><li><span class=\"kw-imagerie\">IRM hypothalamo-hypophysaire</span> systématique</li><li>Recherche d'un <span class=\"kw-etio\">hypopituitarisme</span> ou d'un syndrome <span class=\"kw-etio\">tumoral</span> sellaire</li></ul><h4>Traitement</h4><ul><li><span class=\"kw-ttt\">Lévothyroxine</span>, modalités identiques</li><li><span class=\"kw-ttt\">β-bloquants</span> parfois associés</li></ul><h4><span class=\"kw-def\">Surveillance</span></h4><ul><li>Sur la <span class=\"kw-bio\">T4L</span> — <span class=\"kw-ci\">la TSH n'est pas utilisable</span> (souvent effondrée)</li><li>Contrôle à <span class=\"kw-chiffre\">J15-21</span>, à jeun avant la prise ; objectif <span class=\"kw-bio\">T4L</span> <span class=\"kw-chiffre\">&gt; 50-75 % de la normale</span></li></ul>"}]},"cards":[{"i":"06ced9cdd646","n":243,"o":"243-1","u":"Définition","t":"Connaître la définition de l’hypothyroïdie","q":"Quelles sont les valeurs biologiques caractéristiques pour différencier une hypothyroïdie primaire d'une hypothyroïdie centrale ?","a":"<ul><li><strong>Hypothyroïdie primaire</strong> : <br/>&emsp;- <strong>TSH augmentée</strong> (par levée du rétrocontrôle négatif).<br/>&emsp;- <strong>T4L basse</strong> (forme patente) ou normale (forme fruste).</li><li><strong>Hypothyroïdie centrale</strong> : <br/>&emsp;- <strong>TSH basse, normale ou peu élevée</strong> (généralement &lt; 10-12 mUI/L), mais biologiquement inactive.<br/>&emsp;- <strong>T4L toujours basse</strong>.</li></ul>"},{"i":"768987075124","n":243,"o":"243-1","u":"Définition","t":"Connaître la définition de l’hypothyroïdie","q":"Quelle est la définition générale de l'hypothyroïdie ?","a":"<p>L'hypothyroïdie est une <strong>insuffisance de production d'hormones thyroïdiennes</strong>, résultant soit d'une atteinte de la glande thyroïde elle-même, soit, plus rarement, d'un défaut de stimulation de cette glande.</p>"},{"i":"79c2384c6c3f","n":243,"o":"243-1","u":"Définition","t":"Connaître la définition de l’hypothyroïdie","q":"Quels sont les critères diagnostiques biologiques de l'hypothyroïdie patente et de l'hypothyroïdie fruste (infraclinique) ?","a":"<ul><li><strong>Hypothyroïdie patente</strong> : le diagnostic est posé devant une <strong>TSH &gt; 10 mUI/L</strong> et une <strong>T4L basse</strong>.</li><li><strong>Hypothyroïdie fruste (infraclinique)</strong> : le diagnostic est posé devant une <strong>TSH entre 4 et 10 mUI/L</strong> et une <strong>T4L normale</strong>.</li></ul>"},{"i":"b7f9274847e3","n":243,"o":"243-1","u":"Définition","t":"Connaître la définition de l’hypothyroïdie","q":"Comment distingue-t-on les deux principaux mécanismes physiopathologiques de l'hypothyroïdie ?","a":"<p>On distingue deux mécanismes selon le siège de l'atteinte :</p><ul><li>L'<strong>hypothyroïdie primaire ou périphérique</strong>, qui est due à une atteinte de la glande thyroïde.</li><li>L'<strong>hypothyroïdie centrale ou secondaire</strong>, qui est due à une atteinte hypothalamo-hypophysaire.</li></ul>"},{"i":"6939ad1f167d","n":243,"o":"243-10","u":"Prise en charge","t":"Connaître le principe de l’hormonothérapie substitutive dans l’hypothyroïdie","q":"Comment doit être surveillée et adaptée la lévothyroxine chez une femme enceinte hypothyroïdienne connue ?","a":"<p>Chez une femme enceinte hypothyroïdienne connue, les besoins en lévothyroxine augmentent d'environ <strong>25 à 50 % dès le 1<sup>er</sup> trimestre</strong>. Il faut <strong>augmenter la posologie dès le diagnostic de grossesse</strong>, puis surveiller la TSH <strong>tous les mois</strong> pour la maintenir <strong>inférieure à 2,5 mUI/L</strong>.</p>"},{"i":"6a6b947d929c","n":243,"o":"243-10","u":"Prise en charge","t":"Connaître le principe de l’hormonothérapie substitutive dans l’hypothyroïdie","q":"Quel est le piège à éviter lors du contrôle de la TSH dans le suivi de l'hypothyroïdie ?","a":"<p>Un piège classique est le <strong>contrôle de TSH trop précoce</strong> (avant 4-8 semaines d'instauration ou de modification du traitement), ce qui peut conduire à une augmentation trop rapide des doses en raison de l'inertie thyréotrope, avec un risque de <strong>surdosage</strong>. Tout surdosage en thyroxine est à éviter en raison des risques osseux et cardiovasculaires de la thyrotoxicose.</p>"},{"i":"74db1965de62","n":243,"o":"243-10","u":"Prise en charge","t":"Connaître le principe de l’hormonothérapie substitutive dans l’hypothyroïdie","q":"Quelles sont les modalités d'administration et les posologies usuelles de la lévothyroxine dans l'hypothyroïdie ?","a":"<p>La lévothyroxine est principalement administrée <strong>per os</strong> (comprimé ou solution buvable). En cas de coma myxœdémateux ou d'impossibilité d'avaler, une forme <strong>injectable</strong> est disponible. Les besoins moyens sont de <strong>1 à 1,5 µg/kg/j</strong>, adaptés en fonction de la profondeur de l'hypothyroïdie.</p>"},{"i":"a91fc68f0b63","n":243,"o":"243-10","u":"Prise en charge","t":"Connaître le principe de l’hormonothérapie substitutive dans l’hypothyroïdie","q":"Comment surveille-t-on l'hormonothérapie substitutive dans l'hypothyroïdie primaire et quel est l'objectif thérapeutique ?","a":"<p>Dans l'hypothyroïdie primaire, le paramètre de suivi est la <strong>TSH seule</strong>. L'objectif est de maintenir une <strong>TSH entre 0,5 et 2,5 mUI/L</strong>, y compris pendant la grossesse. Le premier contrôle est réalisé à <strong>4-8 semaines</strong>, puis à <strong>M6</strong>, puis annuellement. Le contrôle doit être effectué à jeun avant la prise de lévothyroxine.</p>"},{"i":"fe3fa7df4491","n":243,"o":"243-10","u":"Prise en charge","t":"Connaître le principe de l’hormonothérapie substitutive dans l’hypothyroïdie","q":"Quel est le traitement de référence de l'hypothyroïdie et ses caractéristiques générales ?","a":"<p>Le traitement de référence de l'hypothyroïdie est une <strong>hormonothérapie substitutive à vie</strong>, reposant sur la <strong>lévothyroxine (L-T4)</strong>.</p>"},{"i":"506e11322c73","n":243,"o":"243-11","u":"Prise en charge","t":"Comprendre les spécificités thérapeutiques du traitement de l’hypothyroïdie chez le sujet âgé et/ou coronarien","q":"Quelle est la particularité d'instauration de la lévothyroxine chez le sujet âgé et/ou coronarien atteint d'hypothyroïdie, et pourquoi ?","a":"<p>Chez le sujet âgé et/ou coronarien, l'instauration de la lévothyroxine doit être <strong>prudente</strong> car le retour à l'euthyroïdie peut <strong>démasquer une coronaropathie</strong>, d'autant plus si l'hypothyroïdie est profonde et ancienne.</p>"},{"i":"974ecea4fc70","n":243,"o":"243-11","u":"Prise en charge","t":"Comprendre les spécificités thérapeutiques du traitement de l’hypothyroïdie chez le sujet âgé et/ou coronarien","q":"Quelles sont les modalités d'instauration du traitement par lévothyroxine chez le sujet âgé et/ou coronarien ?","a":"<ul><li>Posologie initiale faible : <strong>12,5 à 25 µg/j</strong>.</li><li>Augmentation progressive par paliers de <strong>12,5 à 25 µg toutes les 1 à 2 semaines</strong>.</li><li>Chez le coronarien non contrôlé : traiter d'abord la <strong>coronaropathie</strong>, puis normaliser la TSH.</li><li>Cible de TSH revue à la hausse : <strong>≈ 10 mUI/L</strong> en cas de coronaropathie non contrôlée, selon la tolérance.</li></ul>"},{"i":"a5261d7480d2","n":243,"o":"243-11","u":"Prise en charge","t":"Comprendre les spécificités thérapeutiques du traitement de l’hypothyroïdie chez le sujet âgé et/ou coronarien","q":"Quelle surveillance cardiologique est requise lors de l'instauration de la lévothyroxine chez un patient hypothyroïdien avec coronaropathie ?","a":"<ul><li>En cas de <strong>coronaropathie grave</strong> : Surveillance <strong>ECG hebdomadaire</strong> si possible.</li><li>En cas de <strong>coronaropathie récente ou non contrôlée</strong> : <strong>Hospitalisation à l'initiation</strong> avec surveillance clinique et <strong>ECG quotidien</strong>.</li><li>Il est important de prévenir le patient qu'il doit consulter en cas de <strong>douleur thoracique</strong>.</li><li>Les <strong>β-bloquants</strong> peuvent être utiles en association à la lévothyroxine.</li></ul>"},{"i":"022f7f07673c","n":243,"o":"243-4","u":"Diagnostic positif","t":"Connaître les signes cliniques d’une hypothyroïdie","q":"Quels sont les signes cliniques neuromusculaires et neuropsychiques de l'hypothyroïdie ?","a":"<p>Les manifestations neuromusculaires et neuropsychiques sont :</p><ul><li><strong>Syndrome myogène</strong> (déficit moteur, crampes, myalgies).</li><li>Tendinites, arthralgies, neuropathies périphériques.</li><li><strong>Ralentissement idéomoteur</strong>, apathie, troubles de la mémoire.</li></ul>"},{"i":"1ee6877a2c79","n":243,"o":"243-4","u":"Diagnostic positif","t":"Connaître les signes cliniques d’une hypothyroïdie","q":"Quels sont les signes cliniques cutanés et des phanères caractéristiques de l'hypothyroïdie ?","a":"<p>Au niveau de la peau et des phanères, on observe :</p><ul><li>Peau <strong>pâle ou jaunâtre</strong> (carotinodermie).</li><li>Peau <strong>sèche et squameuse</strong>.</li><li><strong>Dépilation diffuse</strong> (« signe de la queue des sourcils »).</li><li>Cheveux <strong>secs et cassants</strong>.</li></ul>"},{"i":"abecd11c168d","n":243,"o":"243-4","u":"Diagnostic positif","t":"Connaître les signes cliniques d’une hypothyroïdie","q":"Comment l'expression clinique de l'hypothyroïdie est-elle modulée ?","a":"<p>L'expression clinique de l'hypothyroïdie est modifiée par :</p><ul><li>Sa <strong>profondeur</strong> (fruste ou profonde).</li><li>Son <strong>ancienneté</strong>.</li><li>Son <strong>origine</strong> (périphérique ou centrale).</li></ul>"},{"i":"b2604683e667","n":243,"o":"243-4","u":"Diagnostic positif","t":"Connaître les signes cliniques d’une hypothyroïdie","q":"Quels sont les signes cliniques communs de l'hypométabolisme associés à l'hypothyroïdie ?","a":"<p>Les signes d'hypométabolisme incluent :</p><ul><li><strong>Asthénie</strong> physique et psycho-intellectuelle, somnolence.</li><li><strong>Hypothermie</strong>, frilosité acquise, diminution de la sudation.</li><li><strong>Constipation</strong> acquise.</li><li><strong>Bradycardie</strong>, hypotension artérielle.</li><li>Prise de poids modeste contrastant avec une perte d'appétit.</li></ul>"},{"i":"e18b5deb363c","n":243,"o":"243-4","u":"Diagnostic positif","t":"Connaître les signes cliniques d’une hypothyroïdie","q":"Comment se manifeste le myxœdème cutanéomuqueux en cas d'hypothyroïdie et quelle est sa valeur discriminante ?","a":"<p>Le myxœdème cutanéomuqueux se caractérise par :</p><ul><li>Peau <strong>infiltrée et épaisse</strong> : doigts boudinés, syndrome du canal carpien, paupières infiltrées, faciès lunaire.</li><li>Voix <strong>raque</strong>, hypoacousie, <strong>macroglossie</strong>, ronflements.</li></ul><p>Sa présence oriente vers une <strong>hypothyroïdie périphérique</strong>, car il est absent dans l'insuffisance thyréotrope centrale.</p>"},{"i":"f1b4ce1e4398","n":243,"o":"243-4","u":"Diagnostic positif","t":"Connaître les signes cliniques d’une hypothyroïdie","q":"Quels sont les retentissements endocriniens possibles de l'hypothyroïdie ?","a":"<p>Les retentissements endocriniens comprennent :</p><ul><li>Troubles de la <strong>libido</strong>.</li><li>Troubles des <strong>règles</strong> (oligoménorrhée, ménorragies, anovulation).</li><li><strong>Galactorrhée</strong> rare (en cas d'hyperprolactinémie possible si hypothyroïdie primaire profonde avec TSH > <strong>50 mUI/L</strong>).</li></ul>"},{"i":"07a074ef9b48","n":243,"o":"243-5","u":"Diagnostic positif","t":"Connaître les anomalies des dosages hormonaux","q":"Quels sont les profils hormonaux de l'hypothyroïdie patente (primaire), de l'hypothyroïdie fruste (primaire) et de l'insuffisance thyréotrope (centrale) ?","a":"<ul><li><strong>Hypothyroïdie patente (primaire)</strong> : <strong>TSH &gt; 10 mUI/L</strong> et <strong>T4L basse</strong>.</li><li><strong>Hypothyroïdie fruste (primaire)</strong> : <strong>TSH entre 4 et 10 mUI/L</strong> et <strong>T4L normale</strong>.</li><li><strong>Insuffisance thyréotrope (centrale)</strong> : <strong>TSH basse, normale ou peu élevée (&lt; 10-12 mUI/L)</strong> et <strong>T4L basse</strong>.</li></ul>"},{"i":"4a61c6f97923","n":243,"o":"243-5","u":"Diagnostic positif","t":"Connaître les anomalies des dosages hormonaux","q":"Quelle est la stratégie de dépistage biologique de première intention de l'hypothyroïdie chez l'adulte ?","a":"<p>La stratégie de dépistage repose sur le dosage de la <strong>TSH seule</strong> en première intention.</p>"},{"i":"60a313b57cda","n":243,"o":"243-5","u":"Diagnostic positif","t":"Connaître les anomalies des dosages hormonaux","q":"Quelles sont les situations physiologiques ou pathologiques pouvant entraîner une élévation fonctionnelle de la TSH et simuler une hypothyroïdie fruste ?","a":"<p>Deux situations principales peuvent faussement élever la TSH :</p><ul><li>Le <strong>vieillissement</strong> : la TSH peut s'élever avec l'âge sans qu'il y ait d'hypothyroïdie avérée.</li><li>L'<strong>obésité</strong> : l'élévation de la TSH est fonctionnelle et réversible après une perte de poids.</li></ul>"},{"i":"9cbfe18e76e7","n":243,"o":"243-5","u":"Diagnostic positif","t":"Connaître les anomalies des dosages hormonaux","q":"Comment différencier une hypothyroïdie fruste d'une insuffisance thyréotrope en présence d'une TSH peu élevée ?","a":"<p>La distinction se fait par le dosage de la <strong>T4 libre</strong> :</p><ul><li>Une <strong>T4L normale</strong> oriente vers une <strong>hypothyroïdie fruste</strong>.</li><li>Une <strong>T4L basse</strong> oriente vers une <strong>insuffisance thyréotrope</strong>.</li></ul>"},{"i":"aa8fa8949989","n":243,"o":"243-5","u":"Diagnostic positif","t":"Connaître les anomalies des dosages hormonaux","q":"Dans quel cas doit-on doser la T4 libre (T4L) lors du bilan étiologique d'une hypothyroïdie ?","a":"<p>Le dosage de la <strong>T4L</strong> est réalisé en <strong>deuxième intention</strong>, uniquement si la <strong>TSH est anormale</strong>. Il permet de déterminer la profondeur de l'hypothyroïdie.</p>"},{"i":"b2f19f248629","n":243,"o":"243-9","u":"Étiologies","t":"Connaître les principales étiologies des hypothyroïdies","q":"Quelles sont les principales causes d'hypothyroïdie primaire ?","a":"<p>Les principales causes sont :</p><ul><li>Les <strong>thyroïdites auto-immunes</strong>, dont la <strong>thyroïdite de Hashimoto</strong> (1<sup>ère</sup> cause en France).</li><li>Les <strong>thyroïdites iatrogènes</strong> après traitements (radiothérapie cervicale, iode radioactif, <strong>amiodarone</strong>, lithium, ITK, immunothérapies).</li><li>Les formes <strong>congénitales</strong> (ectopie thyroïdienne, athyréose).</li><li>La <strong>carence iodée</strong> (1<sup>ère</sup> cause de goitre au niveau mondial).</li></ul>"},{"i":"c625a76f4543","n":243,"o":"243-9","u":"Étiologies","t":"Connaître les principales étiologies des hypothyroïdies","q":"Quand faut-il suspecter une insuffisance thyréotrope comme cause d'hypothyroïdie et quels en sont les mécanismes principaux ?","a":"<p>Une insuffisance thyréotrope doit être suspectée devant des signes d'hypothyroïdie, et impose une <strong>IRM hypophysaire systématique</strong>. Les mécanismes principaux sont :</p><ul><li>Les causes <strong>tumorales ou infiltratives</strong> (adénome hypophysaire +++, méningiome, maladies granulomateuses).</li><li>Les causes <strong>lésionnelles</strong> (traumatisme crânien, apoplexie pituitaire, syndrome de Sheehan, hypophysite lymphocytaire).</li><li>Les causes <strong>iatrogènes</strong> (radiothérapie hypothalamo-hypophysaire, immunothérapie anti-CTLA4).</li><li>Les causes <strong>congénitales</strong>.</li></ul>"},{"i":"cc8410494d54","n":243,"o":"243-9","u":"Étiologies","t":"Connaître les principales étiologies des hypothyroïdies","q":"Quel est le suivi nécessaire après un traitement susceptible d'induire une hypothyroïdie iatrogène ?","a":"<p>Après un traitement iodé (ex: <strong>amiodarone</strong>) ou une radiothérapie cervicale, une thyroïdite iatrogène peut survenir des années plus tard. Un <strong>dosage annuel de la TSH</strong> est donc nécessaire pour dépister une éventuelle hypothyroïdie.</p>"},{"i":"f517ef09ff57","n":243,"o":"243-9","u":"Étiologies","t":"Connaître les principales étiologies des hypothyroïdies","q":"Quelles sont les deux grandes catégories étiologiques d'hypothyroïdies selon le siège de l'atteinte ?","a":"<p>Les hypothyroïdies se classent en :</p><ul><li><strong>Hypothyroïdies primaires</strong> : l'atteinte est au niveau de la glande thyroïde elle-même.</li><li><strong>Insuffisances thyréotropes</strong> (ou centrales) : l'atteinte est au niveau de la région hypothalamo-hypophysaire.</li></ul>"}]};